{
  "headline": "FDA's records trace our supply to a plant classified VAI 121 days after the shortage posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the etomidate shortage on 2022-10-05 and it remains Current as of 2026-10-21.",
      "cites": ["E39", "E33"]
    },
    {
      "text": "The Hikma Farmaceutica (Portugal) plant that manufactures the Civica product used at Corvale General was inspected on 2023-02-03 and classified VAI, 121 days after the shortage posting.",
      "cites": ["D6", "E29", "E32"]
    },
    {
      "text": "The same plant was inspected again on 2023-04-21 and classified VAI, 198 days after the shortage posting.",
      "cites": ["D7", "E30", "E32"]
    },
    {
      "text": "Hospira, Inc., another listed manufacturer, received a Warning Letter on 2010-04-12 and multiple OAI inspections between 2010 and 2011, but its most recent inspection on 2025-02-07 was NAI.",
      "cites": ["E21", "E12", "E14", "E16", "E22"]
    },
    {
      "text": "Corvale East has 7.6 days of etomidate 2 mg/mL 10 mL vials on hand while Corvale General has 17 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The top-ranked option is to transfer 70 vials from Corvale General to Corvale East, which would raise Corvale East to 11 days on hand while Corvale General retains two weeks.",
      "cites": ["D9"]
    },
    {
      "text": "An alternate manufacturer option from Hikma Pharmaceuticals USA Inc. is approved for use with pharmacist verification and dose recalculation.",
      "cites": ["E11", "E40"]
    }
  ]
}
